"""Routes for Csv Preparation, generated by Dryv; the engine implements ExploreCsvPreparationService."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Awaitable, Callable
from typing import Annotated

from fastapi import APIRouter, Body, Depends, Request

from mzizi_engine.api.schemas.api.explore.models.prepare_request import PrepareRequest
from mzizi_engine.api.schemas.api.explore.models.prepare_result import PrepareResult

__all__ = ["ExploreCsvPreparationService", "build_explore_csv_preparation_router"]

type Guard = Callable[[Request], Awaitable[None]]
"""An async FastAPI dependency that raises 401 or 403 before the route runs."""


class ExploreCsvPreparationService(ABC):
    """What Csv Preparation needs from handwritten code. Raise ``fastapi.HTTPException`` for failures."""

    @abstractmethod
    async def prepare_csv(self, *, body: PrepareRequest) -> PrepareResult:
        """Preview (or save, when save_as is set) a cleaned copy of a CSV."""


def build_explore_csv_preparation_router(
    service: ExploreCsvPreparationService, guard: Guard | None = None
) -> APIRouter:
    """Routes for Csv Preparation, delegating to ``service``; ``guard`` protects every route."""

    router = APIRouter(tags=["Csv Preparation"], dependencies=[Depends(guard)] if guard else [])

    @router.post(
        "/v1/explore/csv/prepare",
        response_model=PrepareResult,
        status_code=200,
        summary="Preview (or save, when save_as is set) a cleaned copy of a CSV.",
    )
    async def prepare_csv(
        body: Annotated[PrepareRequest, Body()],
    ) -> PrepareResult:
        return await service.prepare_csv(body=body)

    return router
